import 'dart:convert';

import 'package:flutter/services.dart';

/// Bundled Unicode name table for the special characters dialog
/// (Write 04 §20.2), generated by `tool/unicode/gen_special_chars.py`.
///
/// Asset format: `{"unicode": "16.0.0", "categories": ["Punctuation", …],
/// "chars": [[8594, "RIGHTWARDS ARROW", 1], …]}`.
const specialCharsAssetKey = 'assets/unicode/special_chars.json';

class SpecialChar {
  SpecialChar(this.codePoint, this.name, this.category)
    : _words = name.toLowerCase().split(RegExp(r'[\s-]+'));

  final int codePoint;

  /// Unicode name ("RIGHTWARDS ARROW").
  final String name;

  /// Index into [SpecialCharsCatalog.categories].
  final int category;
  final List<String> _words;

  String get char => String.fromCharCode(codePoint);

  /// "U+2192".
  String get codeLabel =>
      'U+${codePoint.toRadixString(16).toUpperCase().padLeft(4, '0')}';

  /// Whitespace and format characters that render as nothing; the UI shows
  /// a label instead of the glyph.
  bool get isInvisible =>
      codePoint == 0x00A0 ||
      codePoint == 0x00AD ||
      (codePoint >= 0x2000 && codePoint <= 0x200F) ||
      (codePoint >= 0x2028 && codePoint <= 0x202F) ||
      (codePoint >= 0x205F && codePoint <= 0x206F);

  /// Name in sentence case for display ("Rightwards arrow").
  String get displayName =>
      name.isEmpty ? name : name[0] + name.substring(1).toLowerCase();

  @override
  String toString() => 'SpecialChar($codeLabel $name)';
}

class SpecialCharsCatalog {
  SpecialCharsCatalog._(this.unicodeVersion, this.categories, this.all) {
    _byCategory = [for (var i = 0; i < categories.length; i++) <SpecialChar>[]];
    for (final c in all) {
      _byCategory[c.category].add(c);
      _byCodePoint[c.codePoint] = c;
    }
  }

  factory SpecialCharsCatalog.fromJson(String json) {
    final map = jsonDecode(json) as Map<String, dynamic>;
    final cats = [for (final c in map['categories'] as List) c as String];
    final chars = <SpecialChar>[];
    for (final row in map['chars'] as List) {
      final r = row as List;
      final cat = r[2] as int;
      if (cat < 0 || cat >= cats.length) continue;
      chars.add(SpecialChar(r[0] as int, r[1] as String, cat));
    }
    return SpecialCharsCatalog._(
      map['unicode'] as String? ?? '',
      List.unmodifiable(cats),
      List.unmodifiable(chars),
    );
  }

  static final _cache = Expando<Future<SpecialCharsCatalog>>();

  /// Loads the bundled table once per [bundle] (default [rootBundle]).
  static Future<SpecialCharsCatalog> load([AssetBundle? bundle]) {
    final b = bundle ?? rootBundle;
    return _cache[b] ??= () async {
      try {
        final data = await b.load(specialCharsAssetKey);
        return SpecialCharsCatalog.fromJson(
          utf8.decode(
            data.buffer.asUint8List(data.offsetInBytes, data.lengthInBytes),
          ),
        );
      } catch (_) {
        _cache[b] = null;
        rethrow;
      }
    }();
  }

  final String unicodeVersion;
  final List<String> categories;
  final List<SpecialChar> all;
  late final List<List<SpecialChar>> _byCategory;
  final _byCodePoint = <int, SpecialChar>{};

  List<SpecialChar> inCategory(int i) =>
      i < 0 || i >= _byCategory.length ? const [] : _byCategory[i];

  SpecialChar? byCodePoint(int codePoint) => _byCodePoint[codePoint];

  static final _prefixedCode = RegExp(
    r'^(?:u\+|0x|\\u|&#x)([0-9a-f]{1,6});?$',
    caseSensitive: false,
  );

  /// Bare hex needs 4–6 digits, at least one a decimal digit ("2192", not
  /// "cafe").
  static final _bareCode = RegExp(
    r'^(?=[a-f]*[0-9])([0-9a-f]{4,6})$',
    caseSensitive: false,
  );

  /// Characters matching [query], best first:
  /// 1. an exact code point (`U+2192`, `2192`, `0x2192`) or the character
  ///    itself (`→`);
  /// 2. names equal to / starting with the query;
  /// 3. names where every query word is a whole word, then a word prefix;
  /// 4. names containing the query.
  /// Ties keep catalog order (category, then code point).
  List<SpecialChar> search(String query, {int limit = 200}) {
    final raw = query.trim();
    if (raw.isEmpty || limit <= 0) return const [];
    final exact = <SpecialChar>[];
    final runes = raw.runes.toList();
    if (runes.length == 1) {
      final c = _byCodePoint[runes.first];
      if (c != null) exact.add(c);
    }
    final m = _prefixedCode.firstMatch(raw) ?? _bareCode.firstMatch(raw);
    if (m != null) {
      final c = _byCodePoint[int.parse(m.group(1)!, radix: 16)];
      if (c != null && !exact.contains(c)) exact.add(c);
    }
    final q = raw.toLowerCase();
    final tokens = q.split(RegExp(r'[\s-]+')).where((t) => t.isNotEmpty);
    final scored = <(int, int, SpecialChar)>[];
    for (var i = 0; i < all.length; i++) {
      final c = all[i];
      if (exact.contains(c)) continue;
      final s = _score(c, q, tokens);
      if (s != null) scored.add((s, i, c));
    }
    scored.sort((a, b) {
      final d = a.$1.compareTo(b.$1);
      return d != 0 ? d : a.$2.compareTo(b.$2);
    });
    return [
      ...exact,
      for (final s in scored) s.$3,
    ].take(limit).toList(growable: false);
  }

  static int? _score(SpecialChar c, String q, Iterable<String> tokens) {
    final name = c.name.toLowerCase();
    if (name == q) return 0;
    if (name.startsWith('$q ')) return 1;
    var whole = true;
    for (final t in tokens) {
      if (c._words.contains(t)) continue;
      whole = false;
      if (!c._words.any((w) => w.startsWith(t))) {
        return q.length >= 3 && name.contains(q) ? 5 : null;
      }
    }
    if (whole) return name.startsWith(q) ? 1 : 2;
    return name.startsWith(q) ? 3 : 4;
  }
}
